css:
.mdb-asymmetric{
  container-type:inline-size;
  box-sizing:border-box;
  width:100%;
  padding:14px;
  border:1px solid #1b202b;
  border-radius:16px;
  background:linear-gradient(180deg,#11151d 0%,#0a0c12 60%);
  color:#e7eaf1;
  font-family:system-ui,-apple-system,"Segoe UI",sans-serif;
}
.mdb-asymmetric *{box-sizing:border-box}
.mdb-asymmetric-head{display:flex;align-items:center;gap:8px;margin:0 2px 12px}
.mdb-asymmetric-dot{width:8px;height:8px;border-radius:50%;background:#7d97ff;box-shadow:0 0 0 3px rgba(125,151,255,.16)}
.mdb-asymmetric-title{margin:0;font-size:13px;font-weight:600;letter-spacing:-.01em}
.mdb-asymmetric-ver{margin-left:auto;padding:3px 7px;border:1px solid #232a37;border-radius:999px;color:#818b9f;font:500 10px/1 ui-monospace,Menlo,monospace}
.mdb-asymmetric-grid{
  display:grid;
  gap:8px;
  grid-template-columns:repeat(3,minmax(0,1fr));
  grid-template-areas:"a a b" "a a c" "d d d";
}
.mdb-asymmetric-t{
  display:flex;
  flex-direction:column;
  gap:4px;
  min-width:0;
  padding:11px 12px;
  border:1px solid #1c2230;
  border-radius:12px;
  background:#12161f;
  color:inherit;
  font:inherit;
  text-align:left;
  cursor:pointer;
  transition:transform .18s ease,border-color .18s ease,background .18s ease;
}
.mdb-asymmetric-t:hover{transform:translateY(-2px);border-color:#313b52;background:#161b26}
.mdb-asymmetric-t:active{transform:translateY(0)}
.mdb-asymmetric-t:focus-visible{outline:2px solid #7d97ff;outline-offset:2px}
.mdb-asymmetric-a{
  grid-area:a;
  justify-content:flex-end;
  background:radial-gradient(120% 120% at 85% 0%,rgba(125,151,255,.18) 0%,rgba(125,151,255,0) 55%),#12161f;
}
.mdb-asymmetric-b{grid-area:b}
.mdb-asymmetric-c{grid-area:c}
.mdb-asymmetric-d{grid-area:d;flex-direction:row;align-items:center;gap:10px}
.mdb-asymmetric-pills{display:flex;flex-wrap:wrap;gap:4px;margin-bottom:auto}
.mdb-asymmetric-pills span{padding:3px 6px;border:1px solid #232a37;border-radius:6px;color:#8a93a6;font-size:9.5px;white-space:nowrap}
.mdb-asymmetric-k{color:#7b8497;font-size:9.5px;letter-spacing:.05em;text-transform:uppercase}
.mdb-asymmetric-n{font-size:34px;font-weight:650;line-height:1;letter-spacing:-.035em}
.mdb-asymmetric-n2{font-size:17px;font-weight:600;line-height:1;letter-spacing:-.02em}
.mdb-asymmetric-s{color:#697184;font-size:11px}
.mdb-asymmetric-bar{display:block;height:3px;margin-top:2px;border-radius:2px;background:#232a37;overflow:hidden}
.mdb-asymmetric-fill{display:block;width:98%;height:100%;border-radius:2px;background:linear-gradient(90deg,#7d97ff,#a5f3d0)}
.mdb-asymmetric-d .mdb-asymmetric-k{flex:0 0 auto}
.mdb-asymmetric-faces{display:flex;margin-left:2px}
.mdb-asymmetric-face{
  display:grid;
  place-items:center;
  width:22px;height:22px;
  margin-left:-6px;
  border:1px solid #12161f;
  border-radius:50%;
  background:#242c3c;
  color:#c6cde0;
  font:600 9px/1 ui-monospace,Menlo,monospace;
}
.mdb-asymmetric-more{background:#7d97ff;color:#0b0e15}
.mdb-asymmetric-go{margin-left:auto;color:#6d7688;font-size:14px;transition:transform .18s ease,color .18s ease}
.mdb-asymmetric-d:hover .mdb-asymmetric-go{transform:translateX(3px);color:#e7eaf1}
@container (max-width:260px){
  .mdb-asymmetric-grid{grid-template-columns:1fr;grid-template-areas:"a" "b" "c" "d"}
  .mdb-asymmetric-n{font-size:28px}
}
@media (prefers-reduced-motion:reduce){
  .mdb-asymmetric-t{transition:none}
  .mdb-asymmetric-t:hover{transform:none}
  .mdb-asymmetric-go{transition:none}
  .mdb-asymmetric-d:hover .mdb-asymmetric-go{transform:none}
}

.mdb-stat-bento{
  box-sizing:border-box;
  width:100%;
  padding:12px;
  border:1px solid #16221b;
  border-radius:14px;
  background:
    radial-gradient(circle at 1px 1px,rgba(126,242,176,.10) 1px,transparent 1.4px) 0 0/14px 14px,
    #070a08;
  color:#e6f2ea;
  font-family:system-ui,-apple-system,"Segoe UI",sans-serif;
}
.mdb-stat-bento *{box-sizing:border-box}
.mdb-stat-bento-grid{
  display:grid;
  gap:8px;
  grid-template-columns:repeat(2,minmax(0,1fr));
  grid-template-areas:"m m" "s1 s2" "w w";
}
.mdb-stat-bento-t{
  min-width:0;
  padding:11px 12px;
  border:1px solid #17251d;
  border-radius:11px;
  background:rgba(10,15,12,.86);
}
.mdb-stat-bento-main{grid-area:m;display:flex;flex-direction:column;gap:8px}
.mdb-stat-bento-s1{grid-area:s1;display:flex;flex-direction:column;gap:5px}
.mdb-stat-bento-s2{grid-area:s2;display:flex;flex-direction:column;gap:5px}
.mdb-stat-bento-wide{grid-area:w;display:flex;flex-direction:column;gap:7px}
.mdb-stat-bento-row{display:flex;align-items:center;justify-content:space-between;gap:8px}
.mdb-stat-bento-k{color:#68806f;font-size:10px;letter-spacing:.09em;text-transform:uppercase}
.mdb-stat-bento-chip{
  padding:3px 7px;
  border:1px solid rgba(126,242,176,.26);
  border-radius:999px;
  background:rgba(126,242,176,.10);
  color:#7ef2b0;
  font:600 10px/1 ui-monospace,Menlo,monospace;
}
.mdb-stat-bento-n{
  font:650 32px/1 system-ui,-apple-system,sans-serif;
  letter-spacing:-.04em;
  font-variant-numeric:tabular-nums;
  color:#f2fff7;
}
.mdb-stat-bento-n2{
  font:600 19px/1 ui-monospace,Menlo,monospace;
  letter-spacing:-.03em;
  font-variant-numeric:tabular-nums;
}
.mdb-stat-bento-warn{color:#ffd479}
.mdb-stat-bento-sub{color:#5d7265;font-size:10.5px}
.mdb-stat-bento-mono{color:#8fa897;font:500 10.5px/1 ui-monospace,Menlo,monospace}
.mdb-stat-bento-spark{display:flex;align-items:flex-end;gap:3px;height:34px}
.mdb-stat-bento-b{
  flex:1 1 0;
  min-width:0;
  height:6%;
  border-radius:2px 2px 1px 1px;
  background:linear-gradient(180deg,#3ecf8e,#1d6b4c);
  transition:height .6s cubic-bezier(.22,1,.36,1);
}
.mdb-stat-bento-now{background:linear-gradient(180deg,#a8ffd0,#42d99a);box-shadow:0 0 10px rgba(126,242,176,.35)}
.mdb-stat-bento-track{height:6px;border-radius:3px;background:#16211a;overflow:hidden}
.mdb-stat-bento-fill{
  display:block;
  width:0;
  height:100%;
  border-radius:3px;
  background:linear-gradient(90deg,#1d6b4c,#7ef2b0);
  transition:width .8s cubic-bezier(.22,1,.36,1) .1s;
}
@media (prefers-reduced-motion:reduce){
  .mdb-stat-bento-b{transition:none}
  .mdb-stat-bento-fill{transition:none}
}

