var reduce = false;
try { reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}

var bars = root.querySelectorAll('.mdb-stat-bento-b');
var fill = root.querySelector('.mdb-stat-bento-fill');
setTimeout(function () {
  if (!root.isConnected) return;
  bars.forEach(function (b) { b.style.height = (b.getAttribute('data-h') || 0) + '%'; });
  if (fill) fill.style.width = (fill.getAttribute('data-w') || 0) + '%';
}, 20);

function format(v, dec, pre, suf) {
  var parts = v.toFixed(dec).split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return pre + parts.join('.') + suf;
}

root.querySelectorAll('[data-to]').forEach(function (el) {
  var to = parseFloat(el.getAttribute('data-to')) || 0;
  var dec = parseInt(el.getAttribute('data-dec') || '0', 10);
  var pre = el.getAttribute('data-pre') || '';
  var suf = el.getAttribute('data-suf') || '';
  if (reduce) return; // markup already carries the final figure
  var t0 = null;
  function step(ts) {
    if (!root.isConnected) return;
    if (t0 === null) t0 = ts;
    var p = Math.min(1, (ts - t0) / 950);
    var e = 1 - Math.pow(1 - p, 3);
    el.textContent = format(to * e, dec, pre, suf);
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
});

css:
.mdb-feature-bento{
  box-sizing:border-box;
  width:100%;
  padding:12px;
  border-radius:20px;
  background:radial-gradient(140% 100% at 0% 0%,#1a1230 0%,#0b0910 62%);
  color:#ece8ff;
  font-family:system-ui,-apple-system,"Segoe UI",sans-serif;
}
.mdb-feature-bento *{box-sizing:border-box}
.mdb-feature-bento-grid{
  display:grid;
  gap:9px;
  grid-template-columns:repeat(2,minmax(0,1fr));
  grid-template-areas:"lead lead" "b c" "d d";
}
.mdb-feature-bento-t{
  position:relative;
  display:flex;
  flex-direction:column;
  gap:6px;
  min-width:0;
  padding:13px;
  border:1px solid transparent;
  border-radius:15px;
  background:
    linear-gradient(#140f22,#140f22) padding-box,
    linear-gradient(150deg,#2c2246 0%,#1b1630 60%) border-box;
  color:inherit;
  text-decoration:none;
  transition:transform .2s ease,background .2s ease;
}
.mdb-feature-bento-t:hover{
  transform:translateY(-2px);
  background:
    linear-gradient(#191231,#141024) padding-box,
    linear-gradient(150deg,#a78bfa 0%,#4c1d95 55%,#2a2140 100%) border-box;
}
.mdb-feature-bento-t:focus-visible{outline:2px solid #a78bfa;outline-offset:3px}
.mdb-feature-bento-t:active{transform:translateY(0)}
.mdb-feature-bento-lead{grid-area:lead;gap:7px;padding:15px}
.mdb-feature-bento-b{grid-area:b}
.mdb-feature-bento-c{grid-area:c}
.mdb-feature-bento-d{grid-area:d;flex-direction:row;align-items:center;flex-wrap:wrap;gap:11px}
.mdb-feature-bento-icon{
  display:grid;
  place-items:center;
  flex:0 0 auto;
  width:28px;height:28px;
  border:1px solid #35295c;
  border-radius:9px;
  background:linear-gradient(160deg,#251b42,#170f2b);
  color:#c4b5fd;
}
.mdb-feature-bento-icon svg{width:15px;height:15px;display:block}
.mdb-feature-bento-lead .mdb-feature-bento-icon{width:32px;height:32px;border-radius:10px;margin-bottom:auto}
.mdb-feature-bento-lead .mdb-feature-bento-icon svg{width:17px;height:17px}
.mdb-feature-bento-h{margin:0;font-size:13px;font-weight:600;letter-spacing:-.012em}
.mdb-feature-bento-lead .mdb-feature-bento-h{font-size:16px;letter-spacing:-.02em}
.mdb-feature-bento-p{margin:0;color:#9b91bd;font-size:11.5px;line-height:1.45}
.mdb-feature-bento-wrap{display:flex;flex-direction:column;flex:1 1 130px;gap:3px;min-width:0}
.mdb-feature-bento-link{margin-top:2px;color:#c4b5fd;font-size:11.5px;font-weight:550}
.mdb-feature-bento-link span{display:inline-block;transition:transform .2s ease}
.mdb-feature-bento-lead:hover .mdb-feature-bento-link span{transform:translateX(4px)}
.mdb-feature-bento-tag{
  margin-left:auto;
  flex:0 0 auto;
  padding:4px 8px;
  border:1px solid #3b2f63;
  border-radius:999px;
  color:#b9aee0;
  font:600 9.5px/1 ui-monospace,Menlo,monospace;
  letter-spacing:.05em;
  text-transform:uppercase;
}
@media (prefers-reduced-motion:reduce){
  .mdb-feature-bento-t{transition:none}
  .mdb-feature-bento-t:hover{transform:none}
  .mdb-feature-bento-link span{transition:none}
  .mdb-feature-bento-lead:hover .mdb-feature-bento-link span{transform:none}
}

.mdb-flex-bento{
  box-sizing:border-box;
  container-type:inline-size;
  width:100%;
  padding:10px;
  border:1px solid #241f19;
  border-radius:12px;
  background:#0b0a08;
  color:#f0e9df;
  font-family:system-ui,-apple-system,"Segoe UI",sans-serif;
}
.mdb-flex-bento *{box-sizing:border-box}
.mdb-flex-bento-grid{display:flex;gap:6px;height:200px}
.mdb-flex-bento-col{display:flex;flex-direction:column;flex:2.05 1 0;gap:6px;min-width:0}
.mdb-flex-bento-row{
  display:flex;
  flex:1 1 0;
  gap:6px;
  min-height:0;
  transition:flex-grow .32s cubic-bezier(.3,1,.4,1);
}
.mdb-flex-bento-t{
  display:flex;
  flex-direction:column;
  flex:1 1 0;
  gap:4px;
  min-width:0;
  min-height:0;
  overflow:hidden;
  padding:10px;
  border:1px solid #2a241c;
  border-radius:9px;
  background:linear-gradient(170deg,#15120e,#100e0b);
  color:inherit;
  font:inherit;
  text-align:left;
  cursor:pointer;
  transition:flex-grow .32s cubic-bezier(.3,1,.4,1),border-color .25s ease,background .25s ease;
}
.mdb-flex-bento-t:hover{border-color:#6b4f22;background:linear-gradient(170deg,#1d1811,#13100c)}
.mdb-flex-bento-t:focus-visible{outline:2px solid #f0a02c;outline-offset:2px}
.mdb-flex-bento-t3{flex:1.05 1 0}
.mdb-flex-bento-t4{flex:.85 1 0}
.mdb-flex-bento-t1:hover{flex-grow:1.95}
.mdb-flex-bento-t1:focus-within{flex-grow:1.95}
.mdb-flex-bento-t2:hover{flex-grow:1.95}
.mdb-flex-bento-t2:focus-within{flex-grow:1.95}
.mdb-flex-bento-t3:hover{flex-grow:2.1}
.mdb-flex-bento-t3:focus-within{flex-grow:2.1}
.mdb-flex-bento-t4:hover{flex-grow:1.5}
.mdb-flex-bento-t4:focus-within{flex-grow:1.5}
.mdb-flex-bento-row:has(.mdb-flex-bento-t:hover){flex-grow:1.5}
.mdb-flex-bento-row:has(.mdb-flex-bento-t:focus-within){flex-grow:1.5}
.mdb-flex-bento-k{color:#8a7c68;font-size:9px;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}
.mdb-flex-bento-v{margin-top:auto;font-size:24px;font-weight:600;line-height:1;letter-spacing:-.035em;white-space:nowrap}
.mdb-flex-bento-u{margin-left:4px;color:#8a7c68;font-size:10px;font-weight:500;letter-spacing:0}
.mdb-flex-bento-who{margin-top:auto;display:flex;flex-direction:column;align-items:flex-start;gap:5px;min-width:0}
.mdb-flex-bento-face{
  display:grid;place-items:center;
  flex:0 0 auto;width:22px;height:22px;
  border-radius:50%;
  background:#f0a02c;color:#221703;
  font:700 9px/1 ui-monospace,Menlo,monospace;
}
.mdb-flex-bento-name{font-size:11.5px;font-weight:550;line-height:1.2}
.mdb-flex-bento-rel{margin-top:auto;font:600 14px/1 ui-monospace,Menlo,monospace;letter-spacing:-.02em;white-space:nowrap}
.mdb-flex-bento-ok{margin-left:5px;color:#79d99a;font-size:10px;font-weight:600}
.mdb-flex-bento-d{
  max-height:0;
  opacity:0;
  color:#a2937c;
  font-size:11px;
  line-height:1.4;
  transform:translateY(4px);
  transition:max-height .3s ease,opacity .25s ease,transform .3s ease;
}
.mdb-flex-bento-t:hover .mdb-flex-bento-d{max-height:64px;opacity:1;transform:translateY(0)}
.mdb-flex-bento-t:focus-within .mdb-flex-bento-d{max-height:64px;opacity:1;transform:translateY(0)}
@container (max-width:250px){
  .mdb-flex-bento-grid{flex-direction:column;height:auto}
  .mdb-flex-bento-t{min-height:64px}
  .mdb-flex-bento-k{white-space:normal}
}
@media (prefers-reduced-motion:reduce){
  .mdb-flex-bento-row{transition:none}
  .mdb-flex-bento-t{transition:none}
  .mdb-flex-bento-d{transition:none;transform:none}
}

.mdb-media-mix{
  box-sizing:border-box;
  width:100%;
  padding:12px;
  border:1px solid rgba(125,211,252,.14);
  border-radius:18px;
  background:radial-gradient(120% 90% at 100% 0%,#0d2438 0%,#080c14 58%);
  color:#e4f1fb;
  font-family:system-ui,-apple-system,"Segoe UI",sans-serif;
}
.mdb-media-mix *{box-sizing:border-box}
.mdb-media-mix-grid{
  display:grid;
  gap:8px;
  grid-template-columns:88px minmax(0,1fr);
  grid-template-areas:"chart chart" "art copy" "tags tags";
}
.mdb-media-mix-t{
  min-width:0;
  border:1px solid rgba(148,197,232,.12);
  border-radius:13px;
  background:rgba(14,25,38,.72);
  backdrop-filter:blur(6px);
}
.mdb-media-mix-chart{grid-area:chart;display:flex;flex-direction:column;gap:6px;padding:11px 12px 9px}
.mdb-media-mix-row{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.mdb-media-mix-k{color:#7d97ad;font-size:10px;letter-spacing:.09em;text-transform:uppercase}
.mdb-media-mix-val{font:600 17px/1 system-ui,sans-serif;letter-spacing:-.03em;color:#bfe6ff}
.mdb-media-mix-svg{display:block;width:100%;height:52px}
.mdb-media-mix-line{
  stroke-dasharray:260;
  stroke-dashoffset:260;
  animation:mdb-media-mix-draw 1.4s cubic-bezier(.4,0,.2,1) forwards;
}
.mdb-media-mix-area{opacity:0;animation:mdb-media-mix-fade .8s ease .7s forwards}
.mdb-media-mix-axis{display:flex;justify-content:space-between;color:#5b7285;font:500 9px/1 ui-monospace,Menlo,monospace}
.mdb-media-mix-cover{grid-area:art;position:relative;padding:7px;aspect-ratio:1/1}
.mdb-media-mix-art{
  position:relative;
  width:100%;height:100%;
  border-radius:9px;
  overflow:hidden;
  background:
    conic-gradient(from 210deg at 32% 28%,#f472b6 0deg,#818cf8 110deg,#22d3ee 210deg,#0ea5e9 300deg,#f472b6 360deg);
}
.mdb-media-mix-art::after{
  content:"";
  position:absolute;inset:0;
  background:radial-gradient(70% 70% at 30% 25%,rgba(255,255,255,.35),rgba(0,0,0,.55));
  mix-blend-mode:overlay;
}
.mdb-media-mix-eq{position:absolute;left:7px;bottom:7px;z-index:2;display:flex;align-items:flex-end;gap:2px;height:16px}
.mdb-media-mix-eq i{
  width:3px;height:4px;
  border-radius:1px;
  background:rgba(255,255,255,.92);
  animation:mdb-media-mix-bounce .9s ease-in-out infinite alternate;
  animation-play-state:paused;
}
.mdb-media-mix-eq i:nth-child(2){animation-duration:.7s}
.mdb-media-mix-eq i:nth-child(3){animation-duration:1.1s}
.mdb-media-mix-eq i:nth-child(4){animation-duration:.8s}
.mdb-media-mix-on .mdb-media-mix-eq i{animation-play-state:running}
.mdb-media-mix-play{
  position:absolute;right:11px;bottom:11px;
  display:grid;place-items:center;
  width:26px;height:26px;
  padding:0;
  border:0;
  border-radius:50%;
  background:#e8f6ff;
  color:#0b1622;
  cursor:pointer;
  transition:transform .18s ease,background .18s ease;
}
.mdb-media-mix-play svg{width:14px;height:14px}
.mdb-media-mix-play:hover{transform:scale(1.08);background:#fff}
.mdb-media-mix-play:focus-visible{outline:2px solid #7dd3fc;outline-offset:2px}
.mdb-media-mix-play[aria-pressed="true"] svg{transform:scale(.86)}
.mdb-media-mix-copy{grid-area:copy;display:flex;flex-direction:column;gap:3px;padding:11px 12px}
.mdb-media-mix-title{margin:0;font-size:15px;font-weight:600;letter-spacing:-.02em}
.mdb-media-mix-artist{margin:0;color:#8ba7bd;font-size:11.5px}
.mdb-media-mix-state{margin-top:auto;color:#7dd3fc;font:600 10px/1 ui-monospace,Menlo,monospace;letter-spacing:.06em;text-transform:uppercase}
.mdb-media-mix-tags{grid-area:tags;display:flex;flex-wrap:wrap;gap:5px;padding:9px 10px}
.mdb-media-mix-pill{
  padding:4px 8px;
  border:1px solid rgba(148,197,232,.16);
  border-radius:999px;
  color:#a9c6da;
  font-size:10.5px;
}
.mdb-media-mix-hot{border-color:rgba(244,114,182,.35);background:rgba(244,114,182,.12);color:#f9a8d4}
@keyframes mdb-media-mix-draw{to{stroke-dashoffset:0}}
@keyframes mdb-media-mix-fade{to{opacity:1}}
@keyframes mdb-media-mix-bounce{from{height:4px}to{height:15px}}
@media (prefers-reduced-motion:reduce){
  .mdb-media-mix-line{animation:none;stroke-dashoffset:0}
  .mdb-media-mix-area{animation:none;opacity:1}
