js:
var tabs = Array.prototype.slice.call(root.querySelectorAll('.mdb-dash-bento-tab'));
var ring = root.querySelector('.mdb-dash-bento-ring');
var pct = root.querySelector('.mdb-dash-bento-pct');
var big = root.querySelector('.mdb-dash-bento-big');
var delta = root.querySelector('.mdb-dash-bento-delta');
var fills = root.querySelectorAll('.mdb-dash-bento-mfill');

var DATA = {
  '7d':  { p: 72, big: '18,402',  d: '+6.1% vs prior 7d',   m: [64, 41, 88] },
  '30d': { p: 58, big: '74,918',  d: '+3.4% vs prior 30d',  m: [52, 63, 74] },
  '90d': { p: 86, big: '221,540', d: '+11.8% vs prior 90d', m: [81, 49, 60] }
};

function select(btn) {
  var d = DATA[btn.getAttribute('data-range')];
  if (!d) return;
  tabs.forEach(function (t) {
    var on = t === btn;
    t.setAttribute('aria-checked', on ? 'true' : 'false');
    t.tabIndex = on ? 0 : -1;
  });
  if (ring) ring.style.setProperty('--p', d.p);
  if (pct) pct.textContent = d.p + '%';
  if (big) big.textContent = d.big;
  if (delta) delta.textContent = d.d;
  fills.forEach(function (f, i) { f.style.width = d.m[i] + '%'; });
}

tabs.forEach(function (t, i) {
  t.addEventListener('click', function () { select(t); });
  t.addEventListener('keydown', function (e) {
    var dir = e.key === 'ArrowRight' ? 1 : (e.key === 'ArrowLeft' ? -1 : 0);
    if (!dir) return;
    e.preventDefault();
    var next = tabs[(i + dir + tabs.length) % tabs.length];
    select(next);
    next.focus();
  });
});

if (tabs.length) select(tabs[0]);

